H,W=26,24
out=[[6]*W for _ in range(H)]
# Current source pattern, anchored at its middle-left cell (row 13, col 5).
pattern=[[1,0,6],[0,3,0],[9,6,6]]
for i in range(3):
    for j in range(3): out[12+i][5+j]=pattern[i][j]
markers=[(5,12),(8,22),(9,14),(13,15),(14,10),(15,18),(19,7),(22,14),(24,21)]
for r,c in markers:
    for i in range(3):
        for j in range(3):
            rr,cc=r+i-1,c+j
            if 0<=rr<H and 0<=cc<W:
                out[rr][cc]=pattern[i][j]
assert len(out)==26 and all(len(row)==24 for row in out)
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))
